def review_code_for_reason(reason):
    if reason == "Bot administrator rights removed":
        return "bot_admin"
    if reason.startswith("Polling outage"):
        return "history_gap"
    if reason.startswith("Group ID changed"):
        return "group_changed"
    if "admission" in reason.lower():
        return "admission_uncertain"
    if reason.startswith("Manual confirmation"):
        return "manual_history"
    if reason.startswith("Delayed history"):
        return "delayed_history"
    return "unknown"


def review_details(room):
    data = room.get("data", room)
    code = data.get("errorCode") or review_code_for_reason(data.get("error") or "")
    reason, action, retry_label = _REVIEWS.get(code, _REVIEWS["unknown"])
    return {"reason": reason, "action": action, "retryLabel": retry_label,
        "manualRequired": bool(data.get("cleanupUncertain"))}
